from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    mode = inputs.get('mode', 0)

    if mode == 1:
        # GCD of v1..v7
        values = [inputs[f'v{i}'] for i in range(1, 8) if f'v{i}' in inputs]
        return float(reduce(gcd, [int(v) for v in values]))

    elif mode == 2:
        # Look and say
        n = str(int(inputs['N']))
        k = int(inputs['K'])
        for _ in range(k):
            result = []
            i = 0
            while i < len(n):
                ch = n[i]
                count = 1
                while i + count < len(n) and n[i + count] == ch:
                    count += 1
                result.append(str(count) + ch)
                i += count
            n = ''.join(result)
        print(f"Result: {n}")
        return float(n)

    elif mode == 3:
        # Kaprekar
        n = int(inputs['N'])
        k = int(inputs['K'])
        digits = len(str(n))
        for step in range(k):
            s = str(n).zfill(digits)
            big = int(''.join(sorted(s, reverse=True)))
            small = int(''.join(sorted(s)))
            n = big - small
            print(f"Step {step+1}: {n}")
        return float(n)

    elif mode == 4:
        # Simple arithmetic
        return inputs['A'] + inputs['B']

    elif mode == 5:
        # Power mod
        return float(pow(int(inputs['base']), int(inputs['exp']), int(inputs['mod'])))

    else:
        # Default: sum of all numeric inputs
        return sum(v for k2, v in inputs.items() if k2 != 'mode')

